static int p4_validate_current(struct p4_mntns_grant *g)
{
	struct fs_struct *fs;
	bool same;

	if (ktime_get_boottime_ns() >= g->deadline_ns)
		return -ETIME;
	if (task_pid(current) != g->pid || current->mm != g->mm ||
	    current_cred() != g->cred || current_real_cred() != g->cred ||
	    current->nsproxy != g->ns || task_active_pid_ns(current) != g->pid_ns ||
	    current->fs != g->fs || !p4_single_task(current) ||
	    atomic_read(&current->mm->mm_users) != 1 || !p4_no_admin(current_cred()))
		return -ESTALE;
	fs = g->fs;
	read_seqlock_excl(&fs->seq);
	same = fs->users == 2 && !fs->in_exec &&
	       read_seqbegin(&fs->seq) == g->fs_seq && fs->umask == g->fs_umask &&
	       path_equal(&fs->root, &g->root) && path_equal(&fs->pwd, &g->pwd);
	read_sequnlock_excl(&fs->seq);
	return same ? 0 : -ESTALE;
}

